## solution

#### merge sort

```cpp
#include <vector>
#include <math.h>

std::vector<int> merge(std::vector<int> v1, std::vector<int> v2) {
  std::vector<int> merged;

  int i = 0;
  int j = 0;
  while (i < v1.size() && j < v2.size()) {
    if (v1[i] < v2[j]) {
      merged.push_back(v1[i]);
      i += 1;
    } else {
      merged.push_back(v2[j]);
      j += 1;
    }
  }

  while (i < v1.size()) {
      merged.push_back(v1[i]);
      i += 1;
  }

  while (j < v2.size()) {
      merged.push_back(v2[j]);
      j += 1;
  }

  return merged;
}

std::vector<int> mergeSort(std::vector<int> numbers) {
  if (numbers.size() <= 1) {
    return numbers;
  }

  int mid = floor(numbers.size() / 2);
  std::vector<int> left(numbers.begin(), numbers.begin() + mid);
  std::vector<int> right(numbers.begin() + mid, numbers.end());
  std::vector<int> sortedLeft = mergeSort(left);
  std::vector<int> sortedRight = mergeSort(right);
  return merge(sortedLeft, sortedRight);
}
```

- n = array size
- Time: O(nlogn)
- Space: O(n)
